import{_ as e,a as i,b as o,c as l,d as s,e as n,f as p,g as u,h as d,i as h,j as c,k as m,l as P,m as _,n as b,o as f}from"./chunks/4_10_spi_port_jst_gh_7p_connector.eQu3nljK.js";import{_ as S,C,o as A,c as g,j as a,a as T,E as k,al as q}from"./chunks/framework.7vp1BMOE.js";const B=JSON.parse('{"title":"VOLOLAND NarinFC-H7","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/vololand_narinfc_h7.md","filePath":"uk/flight_controller/vololand_narinfc_h7.md"}'),D={name:"uk/flight_controller/vololand_narinfc_h7.md"};function x(N,t,I,v,R,E){const r=C("Badge");return A(),g("div",null,[t[0]||(t[0]=a("h1",{id:"vololand-narinfc-h7",tabindex:"-1"},[T("VOLOLAND NarinFC-H7 "),a("a",{class:"header-anchor",href:"#vololand-narinfc-h7","aria-label":'Permalink to "VOLOLAND NarinFC-H7"'},"​")],-1)),k(r,{type:"tip",text:"PX4 v1.17"}),t[1]||(t[1]=q('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://vololand.com" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The NarinFC-H7 is an advanced flight controller produced by <a href="https://vololand.com" target="_blank" rel="noreferrer">VOLOLAND Inc.</a>. It uses a high-performance STM32H7 processor and integrates industrial-grade sensors for improved performance and reliability.</p><p><img src="'+e+'" alt="NarinFC-H7"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="основні-характеристики" tabindex="-1">Основні характеристики <a class="header-anchor" href="#основні-характеристики" aria-label="Permalink to &quot;Основні характеристики&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>FMU Processor: STM32H743</li><li>Бортові сенсори: <ul><li>Accelerometer/Gyroscope: ADIS16470</li><li>Прискорювач/гіроскоп: ICM-20649</li><li>Акселерометр/Гіроскоп: BMI088</li><li>Магнітометр: RM3100</li><li>Barometer: MS5611 x2</li></ul></li></ul><h3 id="інтерфеиси" tabindex="-1">Інтерфейси <a class="header-anchor" href="#інтерфеиси" aria-label="Permalink to &quot;Інтерфейси&quot;">​</a></h3><ul><li>14 PWM servo outputs</li><li>Multiple RC inputs (SBUS / CPPM / DSM)</li><li>Analog/PWM RSSI input</li><li>2 GPS ports (GPS and UART4)</li><li>4x I2C buses</li><li>2x CAN bus ports</li><li>2x Power ports</li><li>2x ADC ports</li><li>1x USB port</li></ul><h3 id="електричні-дані" tabindex="-1">Електричні дані <a class="header-anchor" href="#електричні-дані" aria-label="Permalink to &quot;Електричні дані&quot;">​</a></h3><ul><li>Power input: 4.3V ~ 5.4V</li><li>USB input: 4.75V ~ 5.25V</li></ul><h3 id="механічні-дані" tabindex="-1">Механічні дані <a class="header-anchor" href="#механічні-дані" aria-label="Permalink to &quot;Механічні дані&quot;">​</a></h3><ul><li>Dimensions: 93.4 x 46.4 x 34.1 mm</li><li>Weight: 106g</li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>Order from <a href="https://vololand.com" target="_blank" rel="noreferrer">VOLOLAND Inc.</a>.</p><h2 id="з-єднання" tabindex="-1">З&#39;єднання <a class="header-anchor" href="#з-єднання" aria-label="Permalink to &quot;З&#39;єднання&quot;">​</a></h2><p><img src="'+i+'" alt="Wire Diagram"></p><h2 id="розміри" tabindex="-1">Розміри <a class="header-anchor" href="#розміри" aria-label="Permalink to &quot;Розміри&quot;">​</a></h2><p><img src="'+o+'" alt="Outline Dimensions"></p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p><img src="'+l+'" alt="Port Diagram A"></p><h3 id="telem1-telem2-port" tabindex="-1">TELEM1 / TELEM2 Port <a class="header-anchor" href="#telem1-telem2-port" aria-label="Permalink to &quot;TELEM1 / TELEM2 Port&quot;">​</a></h3><p><img src="'+s+'" alt="TELEM Pinout"></p><ul><li>JST GH 6P connector</li></ul><h3 id="can1-can2-port" tabindex="-1">CAN1 / CAN2 Port <a class="header-anchor" href="#can1-can2-port" aria-label="Permalink to &quot;CAN1 / CAN2 Port&quot;">​</a></h3><p><img src="'+n+'" alt="CAN Port"></p><ul><li>JST GH 4P connector</li><li>Communication Protocol: UAVCAN v0 (default), UAVCAN v1 (limited support)</li><li>Pin Configuration: CAN_H, CAN_L, VCC, GND</li></ul><h3 id="i2c1-i2c2-i2c3-i2c4-port" tabindex="-1">I2C1, I2C2, I2C3, I2C4 Port <a class="header-anchor" href="#i2c1-i2c2-i2c3-i2c4-port" aria-label="Permalink to &quot;I2C1, I2C2, I2C3, I2C4 Port&quot;">​</a></h3><p><img src="'+p+'" alt="I2C Port"></p><ul><li>JST GH 4P connector</li></ul><h3 id="uart4-port" tabindex="-1">UART4 Port <a class="header-anchor" href="#uart4-port" aria-label="Permalink to &quot;UART4 Port&quot;">​</a></h3><p><img src="'+u+'" alt="UART Port"></p><ul><li>JST GH 6P connector</li></ul><h3 id="rssi-port" tabindex="-1">RSSI Port <a class="header-anchor" href="#rssi-port" aria-label="Permalink to &quot;RSSI Port&quot;">​</a></h3><p><img src="'+d+'" alt="RSSI input"></p><ul><li>RSSI input</li></ul><h3 id="gps-safety-port" tabindex="-1">GPS &amp; Safety Port <a class="header-anchor" href="#gps-safety-port" aria-label="Permalink to &quot;GPS &amp; Safety Port&quot;">​</a></h3><p><img src="'+h+'" alt="GPS &amp; Safety Port"></p><ul><li>JST GH 10P connector</li></ul><p><img src="'+c+'" alt="Port Diagram B"></p><h3 id="pwm-rc-in" tabindex="-1">PWM &amp; RC_IN <a class="header-anchor" href="#pwm-rc-in" aria-label="Permalink to &quot;PWM &amp; RC_IN&quot;">​</a></h3><p>The NarinFC-H7 supports up to 14 PWM outputs.</p><p><img src="'+m+'" alt="PWM Out"></p><ul><li>2.54mm pitch DuPont connector</li><li>RC_IN: Remote control receiver input is wired directly to the FMU and is enabled via the <code>rc_input</code> driver. Compatible with SBUS, CPPM, and DSM protocols.</li></ul><h3 id="power-input" tabindex="-1">Power Input <a class="header-anchor" href="#power-input" aria-label="Permalink to &quot;Power Input&quot;">​</a></h3><p><img src="'+P+'" alt="Power Input"></p><ul><li>2mm pitch DuPont connector</li></ul><h3 id="adc-port" tabindex="-1">ADC Port <a class="header-anchor" href="#adc-port" aria-label="Permalink to &quot;ADC Port&quot;">​</a></h3><p><img src="'+_+'" alt="ADC input"></p><h3 id="debug-uart7-port" tabindex="-1">DEBUG / UART7 Port <a class="header-anchor" href="#debug-uart7-port" aria-label="Permalink to &quot;DEBUG / UART7 Port&quot;">​</a></h3><p>UART7 is labelled DEBUG RX/TX.</p><p><img src="'+b+'" alt="DEBUG Port"></p><ul><li>JST GH 6P connector</li></ul><h3 id="usb-port" tabindex="-1">USB Port <a class="header-anchor" href="#usb-port" aria-label="Permalink to &quot;USB Port&quot;">​</a></h3><ul><li>USB-C</li></ul><h3 id="spi-порт" tabindex="-1">SPI порт <a class="header-anchor" href="#spi-порт" aria-label="Permalink to &quot;SPI порт&quot;">​</a></h3><p><img src="'+f+'" alt="SPI Port"></p><ul><li>JST GH 7P connector</li></ul><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1</td></tr><tr><td>UART4</td><td>/dev/ttyS2</td><td>GPS2</td></tr><tr><td>USART6</td><td>/dev/ttyS3</td><td>TELEM2</td></tr><tr><td>UART8</td><td>/dev/ttyS4</td><td>User</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>Debug</td></tr></tbody></table><h2 id="pwm-output" tabindex="-1">PWM Output <a class="header-anchor" href="#pwm-output" aria-label="Permalink to &quot;PWM Output&quot;">​</a></h2><p>The NarinFC-H7 supports up to 14 PWM outputs. All outputs except M13 and M14 support DShot. Outputs 1-8 support Bi-Directional DShot.</p><p>The 14 PWM outputs are in 4 groups:</p><ul><li>Outputs 1, 2, 3, and 4 in group1</li><li>Outputs 5, 6, 7, and 8 in group2</li><li>Outputs 9, 10, 11, and 12 in group3</li><li>Outputs 13 and 14 in group4</li></ul><p>All outputs within the same group must use the same output rate and protocol.</p><h2 id="analog-inputs" tabindex="-1">Analog Inputs <a class="header-anchor" href="#analog-inputs" aria-label="Permalink to &quot;Analog Inputs&quot;">​</a></h2><p>The NarinFC-H7 has 2 user-accessible analog inputs:</p><ul><li>ADC Pin4 → SPARE1_ADC1 (6.6V tolerant)</li><li>ADC Pin18 → SPARE2_ADC1 (3.3V tolerant)</li></ul><p>Additional internal ADC channels:</p><ul><li>ADC Pin16 → BATT_VOLTAGE_SENS</li><li>ADC Pin17 → BATT_CURRENT_SENS</li><li>ADC Pin14 → BATT2_VOLTAGE_SENS</li><li>ADC Pin2 → BATT2_CURRENT_SENS</li><li>ADC Pin6 → RSSI_IN</li><li>ADC Pin8 → VDD_5V_SENS</li><li>ADC Pin11 → SCALED_V3V3</li></ul><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> narinfc_h7_default</span></span></code></pre></div><h2 id="підтримувані-платформи-конструкціі" tabindex="-1">Підтримувані платформи / Конструкції <a class="header-anchor" href="#підтримувані-платформи-конструкціі" aria-label="Permalink to &quot;Підтримувані платформи / Конструкції&quot;">​</a></h2><p>Будь-який мультикоптер / літак / наземна платформа / човен, який може керуватися звичайними RC сервоприводами або сервоприводами Futaba S-Bus. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p>',76))])}const y=S(D,[["render",x]]);export{B as __pageData,y as default};
